(() => {
  const $=s=>document.querySelector(s),canvas=$('#rooftop-canvas'),ctx=canvas.getContext('2d'),stage=$('#course-stage'),dialog=$('#world-dialog');
  const {Course,roofs,anchors,trackers}=window.RooftopPhysics,game=new Course();const themes=[['#482239','#e49a66','#2c3547'],['#0b2445','#47a9e0','#203d58'],['#0a1f37','#daab63','#2a4055'],['#43213f','#f18dbf','#413858']];
  let world=null,open=false,playing=false,paused=false,started=false,last=0,width=900,height=450,keys=new Set(),touch=new Set(),cameraX=60,camera=null,lastMessage='',lastProgress='',best={},completed=false;
  try{best=JSON.parse(localStorage.getItem('webverse-course-best')||'{}')||{}}catch{}
  function resize(){width=stage.clientWidth||900;height=stage.clientHeight||450;const d=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(width*d);canvas.height=Math.round(height*d);if(ctx)ctx.setTransform(d,0,0,d,0,0)}if(typeof ResizeObserver!=='undefined')new ResizeObserver(resize).observe(stage);resize();
  const timeLabel=n=>Math.floor(n/60)+':'+String(Math.floor(n%60)).padStart(2,'0');
  function announce(){const p=game.player;$('#course-trackers').textContent=game.collected.size+' / 3';$('#course-time').textContent=timeLabel(game.time);$('#course-checkpoint').textContent=game.checkpoint?'ROOF '+(game.checkpoint+1):'START';$('#course-web-state').textContent=game.rope?'WEB / ATTACHED · E TO RELEASE':'WEB / READY';$('#course-web').innerHTML=(game.rope?'Release web':'Attach web')+' <small>E</small>';if(game.message!==lastMessage){lastMessage=game.message;$('#course-message').textContent=game.message}const progress=[...game.collected].sort().join(',')+'|'+game.complete;if(progress!==lastProgress){lastProgress=progress;window.dispatchEvent(new CustomEvent('webverse-course-progress',{detail:{world:world?.index,trackers:[...game.collected],complete:game.complete,time:game.time}}))}if(game.complete&&!completed){completed=true;started=false;best[world.index]=Math.min(Number(best[world.index])||Infinity,game.time);try{localStorage.setItem('webverse-course-best',JSON.stringify(best))}catch{}$('#course-result-copy').textContent='All 3 trackers · '+timeLabel(game.time)+' · '+game.falls+' falls. Best in this world: '+timeLabel(best[world.index])+'.';$('#course-result').hidden=false;$('#course-again').focus()}}
  function reset(start=false){game.reset();started=start;paused=false;completed=false;cameraX=60;keys.clear();touch.clear();lastProgress='';lastMessage='';$('#course-ready').hidden=start;$('#course-result').hidden=true;$('#course-paused').hidden=true;$('#course-pause').textContent='Pause Ⅱ';$('#course-pause').setAttribute('aria-pressed','false');announce();draw()}
  function begin(){if(game.complete)reset(true);started=true;$('#course-ready').hidden=true;canvas.focus({preventScroll:true})}
  function active(){return open&&playing&&!document.hidden}
  function input(){return{x:(keys.has('d')||keys.has('arrowright')||touch.has('right')?1:0)-(keys.has('a')||keys.has('arrowleft')||touch.has('left')?1:0),z:(keys.has('s')||keys.has('arrowdown')||touch.has('back')?1:0)-(keys.has('w')||keys.has('arrowup')||touch.has('forward')?1:0)}}
  function action(type){if(!active()||paused)return;begin();if(type==='jump')game.jump();if(type==='web')game.attach();if(type==='retry')game.respawn(false);announce()}
  document.addEventListener('keydown',e=>{if(!active()||['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase();if(!['a','d','w','s','arrowleft','arrowright','arrowup','arrowdown',' ','e','r'].includes(k))return;e.preventDefault();if(paused)return;if(!started)begin();keys.add(k);if(!e.repeat){if(k===' ')action('jump');if(k==='e')action('web');if(k==='r')action('retry')}});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();touch.clear()});
  document.querySelectorAll('[data-move]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();if(!active()||paused)return;begin();touch.add(b.dataset.move);b.setPointerCapture?.(e.pointerId)});const stop=()=>touch.delete(b.dataset.move);b.addEventListener('pointerup',stop);b.addEventListener('pointercancel',stop);b.addEventListener('lostpointercapture',stop)});
  $('#course-jump').onclick=()=>action('jump');$('#course-web').onclick=()=>action('web');$('#course-retry').onclick=()=>action('retry');$('#course-start').onclick=begin;$('#course-restart').onclick=()=>reset(true);$('#course-again').onclick=()=>reset(true);$('#course-pause').onclick=()=>{paused=!paused;keys.clear();touch.clear();$('#course-paused').hidden=!paused;$('#course-pause').setAttribute('aria-pressed',String(paused));$('#course-pause').textContent=paused?'Resume ▶':'Pause Ⅱ';last=performance.now()};
  function useAnchor(i){if(!active()||paused)return;begin();if(game.rope&&game.rope.index!==i)game.release();game.attach(i);announce()}
  $('#course-anchor-buttons').innerHTML=anchors.map((a,i)=>`<button class="course-anchor" data-course-anchor="${i}" aria-label="Attach web to anchor ${i+1}"><span>✳</span><small>WEB</small></button>`).join('');document.querySelectorAll('[data-course-anchor]').forEach(b=>b.onclick=()=>useAnchor(+b.dataset.courseAnchor));canvas.addEventListener('click',e=>{if(!active()||paused)return;const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;let index=-1,d=Infinity;anchors.forEach((a,i)=>{const p=project(a.x,a.y,a.z);const n=Math.hypot(p.x-x,p.y-y);if(n<d){d=n;index=i}});if(d<100)useAnchor(index);else action('web')});
  window.addEventListener('webverse-enter',e=>{world=e.detail;open=true;playing=true;$('#course-location').textContent=['CLASSIC NEW YORK','NEON MANHATTAN','QUEENS','BROOKLYN / COMIC DIMENSION'][world.index];reset(false);resize()});window.addEventListener('webverse-world-open',e=>{open=e.detail;if(open){resize();draw()}if(!open){keys.clear();touch.clear()}});window.addEventListener('webverse-course-mode',e=>{playing=e.detail;keys.clear();touch.clear();last=performance.now();if(playing){resize();draw()}});window.addEventListener('webverse-course-restart',()=>reset(true));document.addEventListener('visibilitychange',()=>{keys.clear();touch.clear();last=performance.now()});
  function cameraSetup(){const mobile=width<600,eye={x:cameraX-180,y:260,z:mobile?630:750},target={x:cameraX+(mobile?110:180),y:95,z:0};const v={x:target.x-eye.x,y:target.y-eye.y,z:target.z-eye.z};const n=Math.hypot(v.x,v.y,v.z);const f={x:v.x/n,y:v.y/n,z:v.z/n},rn=Math.hypot(f.z,f.x),right={x:-f.z/rn,y:0,z:f.x/rn};const up={x:right.y*f.z-right.z*f.y,y:right.z*f.x-right.x*f.z,z:right.x*f.y-right.y*f.x};camera={eye,f,right,up,focal:mobile?height*1.1:Math.min(width*.85,height*1.65)}}
  function project(x,y,z){if(!camera)cameraSetup();const d={x:x-camera.eye.x,y:y-camera.eye.y,z:z-camera.eye.z},depth=d.x*camera.f.x+d.y*camera.f.y+d.z*camera.f.z,s=camera.focal/Math.max(depth,1);return{x:width*.48+(d.x*camera.right.x+d.y*camera.right.y+d.z*camera.right.z)*s,y:height*.51-(d.x*camera.up.x+d.y*camera.up.y+d.z*camera.up.z)*s,s,depth}}
  function polygon(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>{const q=project(...p);i?ctx.lineTo(q.x,q.y):ctx.moveTo(q.x,q.y)});ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.stroke()}}
  function line(a,b,color,w=2){const p=project(...a),q=project(...b);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(q.x,q.y);ctx.strokeStyle=color;ctx.lineWidth=w;ctx.lineCap='round';ctx.stroke()}
  function platform(r,i){const z=r.depth/2,y=r.y,b=-160;polygon([[r.x,b,z],[r.end,b,z],[r.end,y,z],[r.x,y,z]],'#15273e','#436182');polygon([[r.end,b,-z],[r.end,b,z],[r.end,y,z],[r.end,y,-z]],'#0b1729','#33516e');polygon([[r.x,y,-z],[r.end,y,-z],[r.end,y,z],[r.x,y,z]],themes[world?.index||0][2],'#95a6b8');for(let x=r.x+20;x<r.end;x+=45)line([x,b+15,z+.2],[x,y-20,z+.2],'#e2b96455',3);line([r.x,y+1,-z],[r.end,y+1,-z],'#72bded',2);line([r.x,y+1,z],[r.end,y+1,z],'#ed6b78',2);const p=project(r.x+40,r.y+3,z-30);ctx.fillStyle='#bacfe4';ctx.font='10px sans-serif';ctx.fillText(i===0?'START':'ROOF '+(i+1),p.x,p.y)}
  function character(){const p=game.player,t=game.time,run=p.grounded?Math.sin(t*15)*Math.min(Math.abs(p.vx)/285,1):.4;const a=[p.x,p.y,p.z];line([p.x-5,p.y+23,p.z],[p.x-7+run*9,p.y+3,p.z+run*7],'#2c7ad0',6);line([p.x+5,p.y+23,p.z],[p.x+7-run*9,p.y+3,p.z-run*7],'#2c7ad0',6);line([p.x,p.y+22,p.z],[p.x,p.y+40,p.z],'#e14253',11);line([p.x-3,p.y+35,p.z],[p.x-13-run*7,p.y+25,p.z-4],'#e44b59',4);const hand=game.rope?[p.x+9,p.y+53,p.z]:[p.x+14+run*5,p.y+30,p.z+3];line([p.x+4,p.y+36,p.z],hand,'#f15b64',4);if(game.rope){const anchor=anchors[game.rope.index];line(hand,[anchor.x,anchor.y,anchor.z],'#f3f8ff',2)}const h=project(p.x,p.y+49,p.z);ctx.beginPath();ctx.ellipse(h.x,h.y,Math.max(5,8*h.s),Math.max(7,10*h.s),-.1,0,Math.PI*2);ctx.fillStyle='#ed4c59';ctx.fill();ctx.strokeStyle='#702c44';ctx.lineWidth=1;ctx.stroke();ctx.fillStyle='#fff5ed';ctx.beginPath();ctx.moveTo(h.x-5*h.s,h.y-3*h.s);ctx.lineTo(h.x-1*h.s,h.y);ctx.lineTo(h.x-4*h.s,h.y+3*h.s);ctx.fill();ctx.beginPath();ctx.moveTo(h.x+5*h.s,h.y-3*h.s);ctx.lineTo(h.x+1*h.s,h.y);ctx.lineTo(h.x+4*h.s,h.y+3*h.s);ctx.fill()}
  function draw(){cameraSetup();anchors.forEach((a,i)=>{const p=project(a.x,a.y,a.z),b=document.querySelector('[data-course-anchor="'+i+'"]');b.style.left=p.x+'px';b.style.top=p.y+'px';b.hidden=p.depth<10||p.x<20||p.x>width-20||p.y<18||p.y>height-30;b.classList.toggle('in-range',Math.hypot(game.player.x-a.x,game.player.y+25-a.y,game.player.z-a.z)<=455);b.classList.toggle('attached',game.rope?.index===i)});if(!ctx||!world)return;const theme=themes[world.index],g=ctx.createLinearGradient(0,0,0,height);g.addColorStop(0,theme[0]);g.addColorStop(1,'#081426');ctx.fillStyle=g;ctx.fillRect(0,0,width,height);ctx.fillStyle=theme[1];ctx.globalAlpha=.75;ctx.beginPath();ctx.arc(width*.85,height*.2,27,0,7);ctx.fill();ctx.globalAlpha=1;for(let layer=0;layer<2;layer++){ctx.fillStyle=layer?'#0d2038':'#172b47';for(let i=-1;i<14;i++){const x=i*105-(cameraX*(layer?.16:.06)%105),h=55+(Math.sin(i*7.3+layer)*.5+.5)*125;ctx.fillRect(x,height*.72-h,70+layer*12,height*.5+h)}}[...roofs].reverse().filter(r=>r.end>cameraX-350&&r.x<cameraX+1400).forEach(r=>platform(r,roofs.indexOf(r)));anchors.forEach(a=>{line([a.x,a.y+65,a.z],[a.x,a.y,a.z],'#6688a4',2);const p=project(a.x,a.y+70,a.z);ctx.fillStyle='#9fbcd7';ctx.fillRect(p.x-14,p.y,28,4)});trackers.forEach((t,i)=>{if(game.collected.has(i))return;const p=project(t.x,t.y+Math.sin(game.time*3)*4,t.z);ctx.fillStyle='#ffe3a2';ctx.strokeStyle='#9a6e30';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(p.x,p.y-12);ctx.lineTo(p.x+9,p.y);ctx.lineTo(p.x,p.y+12);ctx.lineTo(p.x-9,p.y);ctx.closePath();ctx.fill();ctx.stroke()});line([1945,35,-60],[1945,155,-60],'#d9e5eb',3);polygon([[1945,155,-60],[2015,143,-60],[1945,118,-60]],game.collected.size===3?'#80e9b5':'#e7b967');const f=project(1940,170,-60);ctx.fillStyle='#e1f0f9';ctx.font='bold 10px sans-serif';ctx.fillText('FINISH',f.x-17,f.y);character()}
  function frame(now){requestAnimationFrame(frame);const dt=Math.min(Math.max((now-last)/1000,0),.05);last=now;if(!active())return;if(started&&!paused&&!completed){game.tick(dt,input());cameraX+=(game.player.x-cameraX)*Math.min(1,dt*7);announce()}draw()}requestAnimationFrame(frame);
})();
